using Topwater;

namespace Topwater.Tests;

/// <summary>Idioms agents reach for: traps for cleanup, find -print0 loops, join/trim/in_array helpers, version checks. Generated from differential runs: each expected value is what bash 5.2.21 printed.</summary>
public class BashCompatIdioms
{
    [Theory]
    [InlineData("set -euo pipefail\ntmp=$(mktemp -d)\ntrap 'rm -rf \"$tmp\"; echo cleaned' EXIT\necho data > \"$tmp/f\"\ncat \"$tmp/f\"", "data\ncleaned\n", 0, true)]
    [InlineData("usage() { echo \"usage: prog <file>\"; }\n[[ $# -eq 0 ]] && { usage; exit 1; }\necho unreachable", "usage: prog <file>\n", 1, true)]
    [InlineData("if [[ -z ${UNSET_VAR+x} ]]; then echo \"is unset\"; fi; EMPTY=; [[ -n ${EMPTY+x} ]] && echo \"is set\"", "is unset\nis set\n", 0, true)]
    [InlineData("touch 'a b.txt' c.txt; while IFS= read -r -d '' f; do echo \"[$f]\"; done < <(find . -name '*.txt' -print0 | sort -z)", "[./a b.txt]\n[./c.txt]\n", 0, true)]
    [InlineData("printf 'a\\0b\\0' > z; mapfile -d '' -t parts < z; echo \"${#parts[@]} ${parts[1]}\"", "2 b\n", 0, true)]
    [InlineData("line=$'one\\ttwo three'; IFS=$'\\t' read -r a b <<< \"$line\"; echo \"[$a] [$b]\"", "[one] [two three]\n", 0, true)]
    [InlineData("hex=ff; echo $(( 16#$hex )); printf -v padded '%05d' 42; echo $padded", "255\n00042\n", 0, true)]
    [InlineData("line=\"first second third\"; read -r first _ <<< \"$line\"; echo \"$first\"", "first\n", 0, true)]
    [InlineData("f() { local -r c=1; c=2; echo \"unreached $c\"; }; f; echo \"after f: $?\"", "", 1, false)]
    [InlineData("init() { declare -gA REG=([k]=v); }; init; echo \"${REG[k]}\"", "v\n", 0, true)]
    [InlineData("s=\"héllo\"; echo ${#s} \"${s:1:1}\" \"${s^^}\"", "5 é HÉLLO\n", 0, true)]
    [InlineData("case 42 in [[:digit:]][[:digit:]]) echo two-digits;; esac", "two-digits\n", 0, true)]
    [InlineData("set -- $(echo \"x y z\"); echo \"$2\"; line=\"a b\"; set -- $line; echo $#", "y\n2\n", 0, true)]
    [InlineData("f() { local IFS=; local s=\"$*\"; echo \"$s\"; }; f a b c", "abc\n", 0, true)]
    [InlineData("keys=(b a c); IFS=$'\\n' read -r -d '' -a sorted < <(printf '%s\\n' \"${keys[@]}\" | sort; printf '\\0'); echo \"${sorted[*]}\"", "a b c\n", 0, true)]
    [InlineData("json_escape() { local s=${1//\\\\/\\\\\\\\}; s=${s//\\\"/\\\\\\\"}; printf '\"%s\"' \"$s\"; }; json_escape 'say \"hi\" \\ ok'; echo", "\"say \\\"hi\\\" \\\\ ok\"\n", 0, true)]
    [InlineData("join() { local IFS=\"$1\"; shift; echo \"$*\"; }; join , a b c; join '' x y", "a,b,c\nxy\n", 0, true)]
    [InlineData("trim() { local v=\"$1\"; v=\"${v#\"${v%%[![:space:]]*}\"}\"; v=\"${v%\"${v##*[![:space:]]}\"}\"; printf '%s' \"$v\"; }; echo \"[$(trim '   hi there  ')]\"", "[hi there]\n", 0, true)]
    [InlineData("in_array() { local n=$1; shift; local e; for e in \"$@\"; do [[ $e == \"$n\" ]] && return 0; done; return 1; }; arr=(a b c); in_array b \"${arr[@]}\" && echo found; in_array z \"${arr[@]}\" || echo missing", "found\nmissing\n", 0, true)]
    [InlineData("str=\"a,b;c d\"; IFS=',; ' read -ra toks <<< \"$str\"; echo \"${#toks[@]}: ${toks[*]}\"", "4: a b c d\n", 0, true)]
    [InlineData("v=3; case $v in 1|2) echo low;; 3|4) echo mid;; *) echo high;; esac", "mid\n", 0, true)]
    [InlineData("printf '%s\\n' \"${!BASH_VERSINFO[@]}\" | tail -1", "5\n", 0, true)]
    [InlineData("x=5; y=$(( x > 3 ? x * 2 : x )); echo $y", "10\n", 0, true)]
    [InlineData("declare -A seen; dups=(); for w in a b a c b; do [[ -n ${seen[$w]:-} ]] && dups+=(\"$w\"); seen[$w]=1; done; echo \"${dups[@]}\"", "a b\n", 0, true)]
    [InlineData("ver1=1.10.2 ver2=1.9.0; if [[ \"$(printf '%s\\n' \"$ver1\" \"$ver2\" | sort -V | head -1)\" == \"$ver2\" ]]; then echo \"$ver1 is newer\"; fi", "1.10.2 is newer\n", 0, true)]
    [InlineData("lower=${1:-DEFAULT}; echo \"${lower,,}\"", "default\n", 0, true)]
    [InlineData("n=0; while :; do (( ++n >= 5 )) && break; done; echo $n", "5\n", 0, true)]
    [InlineData("for f in /etc/hostname /nonexistent; do if [[ -r $f ]]; then echo \"readable: $f\"; else echo \"skip: $f\"; fi; done", "readable: /etc/hostname\nskip: /nonexistent\n", 0, true)]
    [InlineData("out=$( { echo stdout; echo stderr >&2; } 2>/dev/null ); echo \"[$out]\"", "[stdout]\n", 0, true)]
    [InlineData("{ read -r header; while read -r row; do echo \"row: $row\"; done; } <<< $'h\\nr1\\nr2'", "row: r1\nrow: r2\n", 0, true)]
    [InlineData("cnt=$(printf 'a\\nb\\nc\\n' | wc -l); echo $(( cnt + 0 ))", "3\n", 0, true)]
    [InlineData("arr=(); [[ ${#arr[@]} -eq 0 ]] && echo empty; arr+=(\"\"); [[ ${#arr[@]} -eq 1 ]] && echo one-empty", "empty\none-empty\n", 0, true)]
    [InlineData("s=\"key1=val1&key2=val2\"; IFS='&' read -ra pairs <<< \"$s\"; for p in \"${pairs[@]}\"; do echo \"${p%%=*} -> ${p#*=}\"; done", "key1 -> val1\nkey2 -> val2\n", 0, true)]
    [InlineData("path=\"/usr/local/bin:/usr/bin:/bin\"; IFS=: read -ra dirs <<< \"$path\"; echo \"${#dirs[@]} ${dirs[0]}\"; [[ \":$path:\" == *\":/usr/bin:\"* ]] && echo has-usr-bin", "3 /usr/local/bin\nhas-usr-bin\n", 0, true)]
    [InlineData("max() { local m=$1; shift; for n; do (( n > m )) && m=$n; done; echo $m; }; max 3 9 2 7", "9\n", 0, true)]
    [InlineData("repeat() { local s; printf -v s '%*s' \"$2\" ''; echo \"${s// /$1}\"; }; repeat - 5", "-----\n", 0, true)]
    [InlineData("date_re='^[0-9]{4}-[0-9]{2}-[0-9]{2}$'; for d in 2024-01-01 24-1-1; do [[ $d =~ $date_re ]] && echo \"ok $d\" || echo \"bad $d\"; done", "ok 2024-01-01\nbad 24-1-1\n", 0, true)]
    [InlineData("s=\"abc\"; rev=\"\"; for (( i=${#s}-1; i>=0; i-- )); do rev+=${s:i:1}; done; echo $rev", "cba\n", 0, true)]
    [InlineData("declare -A m=([x]=1 [y]=2); for k in $(echo \"${!m[@]}\" | tr ' ' '\\n' | sort); do printf '%s=%s ' \"$k\" \"${m[$k]}\"; done; echo", "x=1 y=2 \n", 0, true)]
    [InlineData("f() { echo \"$#:$*\"; }; f \"${@}\"; set -- \"\" \"\"; f \"$@\"; f $@", "0:\n2: \n0:\n", 0, true)]
    [InlineData("x='a b'; arr=($x \"$x\"); echo ${#arr[@]}", "3\n", 0, true)]
    public Task MatchesBash(string script, string stdout, int exitCode, bool quiet) => BashCompat.Check(script, stdout, exitCode, quiet);
}
